use std::process::{Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};

use opencode_pty::client::TerminalClient;
use opencode_pty::daemon::{REGISTRATION_FILE, Registration};
use opencode_pty::protocol::{Envelope, Request, Response, read_frame, write_frame};
use opencode_pty::service::CreateTerminal;

#[test]
fn daemon_client_read_rows_roundtrip() {
    // Run the Rust client in a child test process so discovery's environment is
    // isolated without mutating this multithreaded test process's environment.
    if let Some(directory) = std::env::var_os("OPENCODE_PTY_ROWS_TEST_CHILD") {
        let directory = std::path::PathBuf::from(directory);
        let client = TerminalClient::discover(&directory).unwrap();
        let mut request = CreateTerminal::shell().unwrap();
        request.program = "/bin/sh".to_string();
        request.args = vec!["-c".to_string(), "printf 'one\ntwo\n\nfour\n'".to_string()];
        request.cols = 10;
        request.rows = 3;
        let terminal = client.create(request).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let rows = client.read_rows(terminal.id, None).unwrap();
            if rows.lines == ["", "four", ""] {
                assert_eq!((rows.terminal.cols, rows.terminal.rows), (10, 3));
                assert_eq!((rows.cursor_x, rows.cursor_y), (0, 2));
                break;
            }
            assert!(Instant::now() < deadline, "terminal output not received");
            thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(client.read_rows(terminal.id, Some(1)).unwrap().lines, [""]);
        assert_eq!(
            client.read_rows(terminal.id, Some(5)).unwrap().lines,
            ["one", "two", "", "four", ""]
        );
        assert!(
            client
                .read_rows(terminal.id, Some(0))
                .unwrap_err()
                .to_string()
                .contains("positive")
        );

        let registration = opencode_pty::daemon::read_registration(&directory).unwrap();
        assert_eq!(registration.protocol, 7);
        // Exercise omitted rows independently of the Rust client's null encoding.
        let mut stream = std::os::unix::net::UnixStream::connect(registration.socket).unwrap();
        write_frame(
            &mut stream,
            &serde_json::json!({
                "token": [REDACTED],
                "request": { "op": "read_rows", "id": terminal.id }
            }),
        )
        .unwrap();
        let response: serde_json::Value = read_frame(&mut stream).unwrap();
        assert_eq!(response["type"], "rows");
        assert_eq!(response["lines"], serde_json::json!(["", "four", ""]));
        assert_eq!(response["terminal"]["id"], terminal.id);
        assert_eq!(response["cursor_y"], 2);
        client.resize(terminal.id, 12, 4).unwrap();
        let rows = client.read_rows(terminal.id, None).unwrap();
        assert_eq!(rows.lines, ["two", "", "four", ""]);
        assert_eq!((rows.terminal.cols, rows.terminal.rows), (12, 4));
        client.terminate(terminal.id).unwrap();
        return;
    }

    let root =
        std::env::temp_dir().join(format!("opencode-pty-rows-{:032x}", rand::random::<u128>()));
    let runtime = root.join("rows");
    let mut daemon = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .args(["daemon", "--name", "rows", "--runtime-dir"])
        .arg(&root)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .spawn()
        .unwrap();
    let deadline = Instant::now() + Duration::from_secs(10);
    while !runtime.join(REGISTRATION_FILE).exists() && Instant::now() < deadline {
        thread::sleep(Duration::from_millis(10));
    }
    let registration: Registration =
        serde_json::from_slice(&std::fs::read(runtime.join(REGISTRATION_FILE)).unwrap()).unwrap();
    let mut owner = std::os::unix::net::UnixStream::connect(&registration.socket).unwrap();
    write_frame(
        &mut owner,
        &Envelope {
            token: [REDACTED],
            request: Request::Own {
                instance_id: registration.instance_id,
                ticket: None,
            },
        },
    )
    .unwrap();
    assert!(matches!(
        read_frame::<Response>(&mut owner).unwrap(),
        Response::Owned
    ));
    let result = Command::new(std::env::current_exe().unwrap())
        .args([
            "--exact",
            "daemon_client_read_rows_roundtrip",
            "--nocapture",
        ])
        .env("OPENCODE_PTY_ROWS_TEST_CHILD", &runtime)
        .output();
    drop(owner);
    assert!(daemon.wait().unwrap().success());
    let _ = std::fs::remove_dir_all(root);
    let output = result.unwrap();
    assert!(
        output.status.success(),
        "{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

#![cfg(unix)]

use std::io::{Read, Write};
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::sync::Barrier;
use std::thread;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use base64::Engine;
use opencode_pty::daemon::Registration;
use opencode_pty::protocol::{
    AttachmentRole, Envelope, Request, Response, read_frame, write_frame,
};
use opencode_pty::service::TerminalInfo;

struct Daemon {
    child: Child,
    root: PathBuf,
    directory: PathBuf,
    registration: Registration,
}

impl Daemon {
    fn start() -> Self {
        let root = std::env::temp_dir().join(format!(
            "opencode-pty-ownership-{:032x}",
            rand::random::<u128>()
        ));
        let directory = root.join("test");
        let mut child = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
            .args(["daemon", "--name", "test", "--runtime-dir"])
            .arg(&root)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .spawn()
            .unwrap();
        let deadline = Instant::now() + Duration::from_secs(3);
        let registration = loop {
            if let Ok(data) = std::fs::read(directory.join("service.json")) {
                break serde_json::from_slice::<Registration>(&data).unwrap();
            }
            assert!(
                child.try_wait().unwrap().is_none(),
                "daemon exited at startup"
            );
            if Instant::now() >= deadline {
                let _ = child.kill();
                let _ = child.wait();
                panic!("daemon did not register");
            }
            thread::sleep(Duration::from_millis(10));
        };
        assert_eq!(registration.protocol, 7);
        Self {
            child,
            root,
            directory,
            registration,
        }
    }

    fn connect(&self) -> UnixStream {
        let stream = UnixStream::connect(&self.registration.socket).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(3)))
            .unwrap();
        stream
            .set_write_timeout(Some(Duration::from_secs(3)))
            .unwrap();
        stream
    }

    fn send(&self, stream: &mut UnixStream, request: Request) -> Response {
        write_frame(
            &mut *stream,
            &Envelope {
                token: [REDACTED],
                request,
            },
        )
        .unwrap();
        read_frame(stream).unwrap()
    }

    fn request(&self, request: Request) -> Response {
        self.send(&mut self.connect(), request)
    }

    fn own(&self, ticket: Option<String>) -> (UnixStream, Response) {
        let mut stream = self.connect();
        let response = self.send(
            &mut stream,
            Request::Own {
                instance_id: self.registration.instance_id.clone(),
                ticket,
            },
        );
        (stream, response)
    }

    fn terminal(&self, command: &str) -> TerminalInfo {
        match self.request(Request::Create {
            program: "/bin/sh".into(),
            args: vec!["-c".into(), command.into()],
            cwd: self.directory.clone(),
            title: "ownership".into(),
            group_id: "ownership".into(),
            env: Default::default(),
            cols: 80,
            rows: 24,
        }) {
            Response::Created { terminal } => terminal,
            response => panic!("create: {response:?}"),
        }
    }

    fn wait(&mut self) {
        self.exit();
        assert!(!self.registration.socket.exists());
    }

    fn exit(&mut self) {
        let deadline = Instant::now() + Duration::from_secs(7);
        loop {
            if let Some(status) = self.child.try_wait().unwrap() {
                assert!(status.success(), "daemon exit: {status}");
                assert!(
                    !self.directory.exists(),
                    "runtime directory was not removed"
                );
                return;
            }
            assert!(Instant::now() < deadline, "daemon did not stop");
            thread::sleep(Duration::from_millis(10));
        }
    }
}

impl Drop for Daemon {
    fn drop(&mut self) {
        if self.child.try_wait().ok().flatten().is_none() {
            if let Ok(mut stream) = UnixStream::connect(&self.registration.socket) {
                let _ = stream.set_write_timeout(Some(Duration::from_secs(1)));
                let _ = write_frame(
                    &mut stream,
                    &Envelope {
                        token: [REDACTED],
                        request: Request::Shutdown,
                    },
                );
            }
            let deadline = Instant::now() + Duration::from_secs(6);
            while self.child.try_wait().ok().flatten().is_none() && Instant::now() < deadline {
                thread::sleep(Duration::from_millis(10));
            }
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

fn assert_terminal_stopped(terminal: &TerminalInfo) {
    // SAFETY: signal zero only checks whether this child PID still exists.
    assert_eq!(unsafe { libc::kill(terminal.pid.unwrap() as i32, 0) }, -1);
    assert_eq!(
        std::io::Error::last_os_error().raw_os_error(),
        Some(libc::ESRCH)
    );
}

