#[test]
fn natural_exit_delivers_contiguous_output_and_retains_final_state() {
    let _deadline = Deadline::new();
    let mut daemon = Daemon::start();
    let (owner, response) = daemon.own(None);
    assert!(matches!(response, Response::Owned));
    let fixture = Fixture::new();
    let terminal = daemon.create(fixture.request());
    let mut child = fixture.connect();
    // Capture a stable process handle before exit; the PID is not terminal identity.
    let process = unsafe {
        OpenProcess(
            PROCESS_SYNCHRONIZE | PROCESS_QUERY_LIMITED_INFORMATION,
            0,
            terminal.pid.unwrap(),
        )
    };
    assert!(!process.is_null());
    let process = unsafe { OwnedHandle::from_raw_handle(process) };

    child.command(FixtureCommand::Output(
        "\x1b[2J\x1b[HBEFORE_ATTACH_MARKER\r\n".into(),
    ));
    daemon.wait_text(terminal.id, "BEFORE_ATTACH_MARKER");
    let (mut subscription, response) =
        daemon.attach(terminal.id, "exit-observer", AttachmentRole::Observer);
    let Response::Attached {
        requested_offset,
        available_offset,
        end_offset,
        truncated,
        replay_base64,
        ..
    } = response
    else {
        panic!("attach: {response:?}");
    };
    assert_eq!(requested_offset, 0);
    assert_eq!(available_offset, 0);
    assert!(!truncated);
    let mut bytes = base64::engine::general_purpose::STANDARD
        .decode(replay_base64)
        .unwrap();
    assert_eq!(end_offset, bytes.len() as u64);
    assert!(String::from_utf8_lossy(&bytes).contains("BEFORE_ATTACH_MARKER"));
    let mut offset = end_offset;

    child.command(FixtureCommand::Output("\r\nFINAL_DAEMON_MARKER\r\n".into()));
    child.command(FixtureCommand::Exit(23));
    let exit_code = loop {
        match read_subscription_event(&mut subscription).unwrap() {
            SubscriptionEvent::Output {
                start,
                end,
                bytes: output,
            } => {
                assert_eq!(
                    start, offset,
                    "output must be contiguous after attachment replay"
                );
                assert_eq!(end - start, output.len() as u64);
                bytes.extend(output);
                offset = end;
            }
            SubscriptionEvent::Response(response) => match *response {
                Response::Exited {
                    exit_code,
                    final_offset,
                } => {
                    assert_eq!(final_offset, offset);
                    break exit_code;
                }
                Response::Error { message } => panic!("subscription: {message}"),
                _ => {}
            },
        }
    };
    drop(subscription);
    assert!(String::from_utf8_lossy(&bytes).contains("FINAL_DAEMON_MARKER"));
    // SAFETY: the live owned process handle permits waiting and exit-code queries.
    assert_eq!(
        unsafe { WaitForSingleObject(process.as_raw_handle(), 3000) },
        WAIT_OBJECT_0
    );
    let mut actual_exit = 0;
    assert_ne!(
        unsafe { GetExitCodeProcess(process.as_raw_handle(), &mut actual_exit) },
        0
    );
    assert_eq!(actual_exit, 23);
    assert_eq!(exit_code, Some(actual_exit));

    let (info, text) = daemon.snapshot(terminal.id);
    assert_eq!(info.lifecycle, TerminalLifecycle::Exited { exit_code });
    assert_eq!(info.output_tail, offset);
    assert!(text.contains("FINAL_DAEMON_MARKER"), "{text:?}");
    let Response::Rows {
        terminal: rows_info,
        lines,
        ..
    } = daemon.request(Request::ReadRows {
        id: terminal.id,
        rows: None,
    })
    else {
        panic!("rows response");
    };
    assert_eq!(rows_info.lifecycle, info.lifecycle);
    assert_eq!(rows_info.output_tail, offset);
    assert!(
        lines
            .iter()
            .any(|line| line.contains("FINAL_DAEMON_MARKER"))
    );
    let Response::Replay {
        requested_offset,
        available_offset,
        end_offset,
        truncated,
        data_base64,
    } = daemon.request(Request::Replay {
        id: terminal.id,
        offset: 0,
    })
    else {
        panic!("replay response");
    };
    assert_eq!(requested_offset, 0);
    assert_eq!(available_offset, 0);
    assert_eq!(end_offset, offset);
    assert!(!truncated);
    assert_eq!(
        base64::engine::general_purpose::STANDARD
            .decode(data_base64)
            .unwrap(),
        bytes
    );
    assert!(
        matches!(daemon.own(None).1, Response::Error { .. }),
        "terminal exit must not lose the live owner"
    );
    assert!(matches!(
        daemon.request(Request::Terminate { id: terminal.id }),
        Response::Ok
    ));
    assert!(
        matches!(daemon.request(Request::List), Response::Terminals { terminals } if terminals.is_empty())
    );
    assert!(matches!(daemon.request(Request::Shutdown), Response::Ok));
    drop(owner);
    daemon.wait();
}

#[test]
fn observer_disconnect_and_control_input_preserve_independent_terminals() {
    let _deadline = Deadline::new();
    let mut daemon = Daemon::start();
    let (owner, response) = daemon.own(None);
    assert!(matches!(response, Response::Owned));
    let first_fixture = Fixture::new();
    let second_fixture = Fixture::new();
    let first = daemon.create(first_fixture.request());
    let second = daemon.create(second_fixture.request());
    assert_ne!(first.id, second.id);
    let mut first_child = first_fixture.connect();
    let mut second_child = second_fixture.connect();
    let (first_control, response) =
        daemon.attach(first.id, "first-controller", AttachmentRole::Controller);
    assert!(matches!(response, Response::Attached { .. }));
    let (second_control, response) =
        daemon.attach(second.id, "second-controller", AttachmentRole::Observer);
    assert!(matches!(response, Response::Attached { .. }));
    let (observer, response) =
        daemon.attach(first.id, "disposable-observer", AttachmentRole::Observer);
    assert!(matches!(response, Response::Attached { .. }));
    drop(observer);

    let first_input = b"first-directed";
    assert!(matches!(
        daemon.request(Request::Input {
            id: first.id,
            attachment_id: "first-controller".into(),
            cols: 91,
            rows: 27,
            data_base64: base64::engine::general_purpose::STANDARD.encode(first_input),
        }),
        Response::Ok
    ));
    assert_eq!(
        first_child.command(FixtureCommand::Read(first_input.len())),
        serde_json::json!(first_input)
    );
    wait_size(&mut first_child, 91, 27);

    assert!(matches!(
        daemon.request(Request::Control {
            id: second.id,
            attachment_id: "second-controller".into(),
            cols: 73,
            rows: 29,
        }),
        Response::Ok
    ));
    wait_size(&mut second_child, 73, 29);
    let second_input = b"second-directed";
    assert!(matches!(
        daemon.request(Request::Input {
            id: second.id,
            attachment_id: "second-controller".into(),
            cols: 74,
            rows: 30,
            data_base64: base64::engine::general_purpose::STANDARD.encode(second_input),
        }),
        Response::Ok
    ));
    assert_eq!(
        second_child.command(FixtureCommand::Read(second_input.len())),
        serde_json::json!(second_input)
    );
    wait_size(&mut second_child, 74, 30);
    assert_eq!(
        first_child.command(FixtureCommand::Size),
        serde_json::json!([91, 27])
    );
    first_child.command(FixtureCommand::Output(
        "\x1b[2J\x1b[HFIRST_ONLY_MARKER".into(),
    ));
    second_child.command(FixtureCommand::Output(
        "\x1b[2J\x1b[HSECOND_ONLY_MARKER".into(),
    ));
    let (first_info, first_text) = daemon.wait_text(first.id, "FIRST_ONLY_MARKER");
    let (second_info, second_text) = daemon.wait_text(second.id, "SECOND_ONLY_MARKER");
    assert_eq!(first_info.lifecycle, TerminalLifecycle::Running);
    assert_eq!(second_info.lifecycle, TerminalLifecycle::Running);
    assert!(!first_text.contains("SECOND_ONLY_MARKER"));
    assert!(!second_text.contains("FIRST_ONLY_MARKER"));
    assert!(
        matches!(daemon.request(Request::List), Response::Terminals { terminals } if terminals.len() == 2)
    );
    assert!(
        matches!(daemon.request(Request::Ping), Response::Pong { instance_id, pid, protocol: 7 }
        if instance_id == daemon.registration.instance_id && pid == daemon.registration.pid)
    );
    assert!(matches!(daemon.own(None).1, Response::Error { .. }));

    assert!(matches!(
        daemon.request(Request::Terminate { id: first.id }),
        Response::Ok
    ));
    drop(first_control);
    assert!(
        matches!(daemon.request(Request::List), Response::Terminals { terminals }
        if terminals.len() == 1 && terminals[0].id == second.id)
    );
    let input = b"after-first-exit";
    assert!(matches!(
        daemon.request(Request::Input {
            id: second.id,
            attachment_id: "second-controller".into(),
            cols: 74,
            rows: 30,
            data_base64: base64::engine::general_purpose::STANDARD.encode(input),
        }),
        Response::Ok
    ));
    assert_eq!(
        second_child.command(FixtureCommand::Read(input.len())),
        serde_json::json!(input)
    );
    second_child.command(FixtureCommand::Output("\r\nSECOND_SURVIVES\r\n".into()));
    assert_eq!(
        daemon.wait_text(second.id, "SECOND_SURVIVES").0.lifecycle,
        TerminalLifecycle::Running
    );
    drop(second_control);
    assert!(matches!(
        daemon.request(Request::Terminate { id: second.id }),
        Response::Ok
    ));
    assert!(matches!(daemon.request(Request::Shutdown), Response::Ok));
    drop(owner);
    daemon.wait();
}

#![cfg(unix)]

use std::ffi::OsStr;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use std::time::{SystemTime, UNIX_EPOCH};

fn runtime_root(name: &str) -> PathBuf {
    std::env::temp_dir().join(format!(
        "opencode-pty-test-{name}-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock")
            .as_nanos()
    ))
}

fn target(root: &Path) -> [&OsStr; 4] {
    [
        OsStr::new("--name"),
        OsStr::new("play"),
        OsStr::new("--runtime-dir"),
        root.as_os_str(),
    ]
}

fn output_with_timeout(mut child: std::process::Child) -> std::process::Output {
    let deadline = Instant::now() + Duration::from_secs(10);
    while Instant::now() < deadline {
        if child.try_wait().expect("child status").is_some() {
            return child.wait_with_output().expect("child output");
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    let _ = child.kill();
    let output = child.wait_with_output().expect("timed out child output");
    panic!(
        "child timed out\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

fn created_terminal_id(output: &[u8]) -> String {
    let output = String::from_utf8_lossy(output);
    let marker = "created terminal ";
    let start = output.find(marker).expect("created terminal output") + marker.len();
    output[start..]
        .split_whitespace()
        .next()
        .expect("terminal ID")
        .to_string()
}

fn read_created_terminal(child: &mut std::process::Child) -> String {
    let mut stdout = BufReader::new(child.stdout.as_mut().expect("stdout"));
    loop {
        let mut line = String::new();
        assert_ne!(stdout.read_line(&mut line).expect("playground output"), 0);
        if line.contains("created terminal ") {
            return line;
        }
    }
}

#[test]
fn playground_proves_authoritative_query_response() {
    let root = runtime_root("query");
    let runtime = root.join("play");
    let mut child = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .arg("play")
        .args(target(&root))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("playground starts");
    child
        .stdin
        .as_mut()
        .expect("stdin")
        .write_all(b"demo\nwait 50\nquit\n")
        .expect("commands written");
    let output = output_with_timeout(child);
    assert!(!runtime.join("service.json").exists());
    assert!(!runtime.exists(), "runtime directory was not removed");
    std::fs::remove_dir_all(&root).unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("QUERY_RESPONSE_OK"), "{stdout}");
}

#[test]
fn playground_exit_stops_all_terminals_and_observers_do_not_start_daemons() {
    let root = runtime_root("ownership");
    let runtime = root.join("play");
    let mut owner = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .arg("play")
        .args(target(&root))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("playground starts");
    let pids = (0..2)
        .map(|_| {
            owner
                .stdin
                .as_mut()
                .unwrap()
                .write_all(b"new /bin/cat\n")
                .unwrap();
            let line = read_created_terminal(&mut owner);
            line.split_once("Some(")
                .unwrap()
                .1
                .trim_end()
                .trim_end_matches("))")
                .parse::<i32>()
                .unwrap()
        })
        .collect::<Vec<_>>();

    let second = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .arg("play")
        .args(target(&root))
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map(output_with_timeout)
        .unwrap();
    assert!(
        !second.status.success(),
        "second playground must not adopt the live daemon"
    );
    for command in ["list", "status"] {
        assert!(
            Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
                .arg(command)
                .args(target(&root))
                .output()
                .unwrap()
                .status
                .success()
        );
    }
    owner.stdin.as_mut().unwrap().write_all(b"quit\n").unwrap();
    assert!(output_with_timeout(owner).status.success());
    assert!(!runtime.join("service.json").exists());
    for pid in pids {
        // SAFETY: signal zero only checks whether the terminal PID still exists.
        assert_eq!(unsafe { libc::kill(pid, 0) }, -1);
        assert_eq!(
            std::io::Error::last_os_error().raw_os_error(),
            Some(libc::ESRCH)
        );
    }
    for args in [&["list"][..], &["status"], &["watch", "1"]] {
        assert!(
            !Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
                .args(args)
                .args(target(&root))
                .output()
                .unwrap()
                .status
                .success()
        );
        assert!(!runtime.join("service.json").exists());
    }
    assert!(!runtime.exists(), "runtime directory was not removed");
    std::fs::remove_dir_all(&root).unwrap();
}

#[test]
fn observer_stream_replays_and_follows_until_exit() {
    let root = runtime_root("stream");
    let runtime = root.join("play");
    let mut owner = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .arg("play")
        .args(target(&root))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("playground starts");
    owner
        .stdin
        .as_mut()
        .expect("stdin")
        .write_all(b"new /bin/sh -c \"printf watched; sleep 2; printf followed\"\n")
        .unwrap();
    let terminal_id = created_terminal_id(read_created_terminal(&mut owner).as_bytes());

    let watched = Command::new(env!("CARGO_BIN_EXE_opencode-pty"))
        .args(["watch", &terminal_id])
        .args(target(&root))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map(output_with_timeout)
        .expect("observer exits with terminal");
    owner.stdin.as_mut().unwrap().write_all(b"quit\n").unwrap();
    assert!(output_with_timeout(owner).status.success());
    assert!(!runtime.join("service.json").exists());
    assert!(!runtime.exists(), "runtime directory was not removed");
    std::fs::remove_dir_all(&root).unwrap();
    assert!(
        watched.status.success(),
        "watch failed with {:?}: {}",
        watched.status.code(),
        String::from_utf8_lossy(&watched.stderr)
    );
    assert!(String::from_utf8_lossy(&watched.stdout).contains("watched"));
    assert!(String::from_utf8_lossy(&watched.stdout).contains("followed"));
}

use super::*;
use std::panic::{AssertUnwindSafe, catch_unwind};

fn terminal() -> Terminal {
    Terminal::new(TerminalOptions {
        cols: 20,
        rows: 5,
        max_scrollback: 1024,
    })
    .unwrap()
}

#[test]
fn callbacks_survive_moves_and_return_owned_data() {
    let mut terminals = vec![terminal()];
    let mut terminal = terminals.pop().unwrap();
    terminal.vt_write(b"\x1b[5n\x1b]2;first\x07");
    assert_eq!(
        terminal.take_writes(),
        VecDeque::from([b"\x1b[0n".to_vec()])
    );
    let title = terminal.take_title().unwrap();
    terminal.vt_write(b"\x1b[5n\x1b]2;second\x07");
    assert_eq!(title, "first");
    assert_eq!(terminal.take_title().as_deref(), Some("second"));
    assert_eq!(
        terminal.take_writes(),
        VecDeque::from([b"\x1b[0n".to_vec()])
    );
    assert!(terminal.take_title().is_none());
    assert!(terminal.take_writes().is_empty());
}

#[test]
fn empty_native_values_and_small_buffers_are_safe() {
    assert!(
        Terminal::new(TerminalOptions {
            cols: 0,
            rows: 1,
            max_scrollback: 0
        })
        .is_err()
    );
    let mut terminal = terminal();
    assert_eq!(terminal.title().unwrap(), "");
    assert!(terminal.format(Format::Plain).unwrap().is_empty());
    assert_eq!(terminal.format_row(0, &mut []).unwrap(), 0);
    assert_eq!(terminal.selection_text(&mut []).unwrap(), None);
    terminal.vt_write("a\u{301}界".as_bytes());
    assert!(terminal.format_row(0, &mut [0; 1]).is_err());
    let mut buffer = [0; 32];
    let len = terminal.format_row(0, &mut buffer).unwrap();
    assert_eq!(&buffer[..len], "a\u{301}界".as_bytes());
    assert!(terminal.format_row(1000, &mut buffer).is_err());
    assert!(terminal.resize(0, 5).is_err());
}

#[test]
fn formatted_bytes_outlive_the_native_terminal() {
    let bytes = {
        let mut terminal = terminal();
        terminal.vt_write("hello 界".as_bytes());
        terminal.format(Format::Plain).unwrap()
    };
    assert_eq!(bytes, "hello 界".as_bytes());
}

#[test]
fn callback_panics_are_resumed_outside_the_c_boundary() {
    let mut terminal = terminal();
    for resize in [false, true] {
        // Deliberately provoke an assertion panic inside the callback. It must return
        // normally to C; either mutating wrapper resumes the panic later in Rust.
        unsafe {
            Effects::write_pty(
                terminal.raw.as_ptr(),
                terminal.effects.userdata().cast_mut(),
                ptr::null(),
                1,
            )
        };
        assert!(
            catch_unwind(AssertUnwindSafe(|| {
                if resize {
                    terminal.resize(30, 10).unwrap();
                } else {
                    terminal.vt_write(b"");
                }
            }))
            .is_err()
        );
    }
    terminal.vt_write(b"\x1b[5n");
    assert_eq!(
        terminal.take_writes(),
        VecDeque::from([b"\x1b[0n".to_vec()])
    );
}
